findings.codeql_raw_query:
/**
 * @name Symlink attack via lock file path
 * @description Lock file paths derived from untrusted input may allow symlink attacks
 * @kind path-problem
 * @problem.severity warning
 * @id filelock/symlink-path
 * @tags security
 *        external/cwe/cwe-61
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs
import semmle.python.Concepts

module SymlinkConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::Node).asExpr() = sink.asExpr()
    )
  }
}

module SymlinkFlow = TaintTracking::Global<SymlinkConfig>;
import SymlinkFlow::PathGraph

from SymlinkFlow::PathNode source, SymlinkFlow::PathNode sink
where SymlinkFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted input flows to $@.", source.getNode(), "file path"
